#include "stdlib/math/base/special/minn.h"
#include "stdlib/math/base/assert/is_nan.h"
#include "stdlib/constants/float64/ninf.h"
#include "stdlib/constants/float64/pinf.h"
#include "stdlib/math/base/assert/is_negative_zero.h"
#include <stddef.h>

/**
* Returns the minimum value.
*
* @param count        number of elements
* @param values       pointer to array of doubles
* @returns            minimum value
*
* @example
* double vals[] = {4.2};
* double v = stdlib_base_minn( 1, vals );
* // returns 4.2
*
* @example
* double vals[] = {3.14, 4.2};
* double v = stdlib_base_minn( 2, vals );
* // returns 3.14
*
* @example
* double vals[] = {NaN};
* double v = stdlib_base_minn( 1, vals );
* // returns NaN
*
* @example
* double vals[] = {-0.0};
* double v = stdlib_base_minn( 1, vals );
* // returns -0.0
*/
double stdlib_base_minn(int count, const double* values ) {
	if ( count <= 0 || values == NULL) {
		return STDLIB_CONSTANT_FLOAT64_PINF;
	}

	double m = STDLIB_CONSTANT_FLOAT64_PINF;

	for ( int i = 0; i < count; i++ ) {
		double val = values[ i ];
		if ( stdlib_base_is_nan( val ) || val == STDLIB_CONSTANT_FLOAT64_NINF ) {
			return val;
		}
		if ( val < m ) {
			m = val;
		} else if ( val == m && val == 0.0 && stdlib_base_is_negative_zero( val ) ) {
			// cppcheck-suppress redundantAssignment
			m = val;
		}
	}
	return m;
}
